    # would otherwise double-buy on exactly the broker this check exists for.
    class _LegacyBroker:
        pass

    with pytest.raises(RuntimeError):
        _same_stream_order_exists(cast(Any, _LegacyBroker()), "AAPL", date(2026, 6, 29))


