def test_run_daily_compact_does_not_merge_across_different_intraday_slots(tmp_path):
    """The intraday stream covers three distinct scheduled times (11:30,
    13:30, 14:30 ET) that all share stream="intraday" and manual_run=False --
    stream alone cannot tell them apart. A later intraday slot reusing the
    same artifacts_dir as an earlier one on the same day must not be
    misread as a retry of the EARLIER slot (Codex review: "Include the
    scheduled slot in retry identity").
    """
    from near_close_dca import _CSV_FIELDS

    artifacts_dir = os.path.join(tmp_path, "runs", "2026-06-29")
    os.makedirs(artifacts_dir, exist_ok=True)
    now, config, state, broker, fin, rh = _compact_setup(tmp_path)

    # Seed a prior run_state.json + orders.csv as if the 11:30 intraday slot
    # had already run in this directory today.
    prior_run_state = {
        "trading_day": "2026-06-29",
        "run_classification": {
            "stream": "intraday",
            "manual_run": False,
            "scheduled_for_et": "11:30",
        },
    }
    with open(os.path.join(artifacts_dir, "run_state.json"), "w", encoding="utf-8") as handle:
        json.dump(prior_run_state, handle)
    with open(os.path.join(artifacts_dir, "orders.csv"), "w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=_CSV_FIELDS)
        writer.writeheader()
        writer.writerow(
            {field: "" for field in _CSV_FIELDS}
            | {
                "ticker": "ZZZZ_1130_SENTINEL",
                "status": "filled",
                "order_id": "sentinel-order-id",
            }
        )

    # The 13:30 slot reuses the same directory on the same trading day --
    # same stream, but NOT a retry of the 11:30 run.
    run_daily_compact(
        now,
        config,
        state,
        fin,
        rh,
        broker,
        options=CompactRunOptions(
            artifacts_dir=artifacts_dir,
            run_label="daily",
            scheduled=True,
            stream="intraday",
            classification_overrides={"stream": "intraday", "scheduled_for_et": "13:30"},
        ),
    )

    with open(os.path.join(artifacts_dir, "orders.csv"), encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    tickers = {row["ticker"] for row in rows}
    assert "ZZZZ_1130_SENTINEL" not in tickers, (
        "the 11:30 slot's execution row was merged into the 13:30 slot's orders.csv"
    )


def test_run_daily_compact_does_not_merge_a_live_and_a_dry_run_attempt(tmp_path):
    """A prior state that explicitly recorded a DIFFERENT dry_run mode (as
    only the success path -- build_run_artifacts -- ever does; the failure
    writer never stamps this field, so an unknown prior mode stays fail-open)
    must not be treated as the same run: copying a live attempt's submitted
    candidate into a dry_run retry (or vice versa) would misattribute real
    capital to a simulated run, or a simulated fill to a real one (Codex
    review: "Keep live and dry-run attempts out of the same retry merge").
    """
    from near_close_dca import _CSV_FIELDS

    artifacts_dir = os.path.join(tmp_path, "runs", "2026-06-29")
    os.makedirs(artifacts_dir, exist_ok=True)
    now, config, state, broker, fin, rh = _compact_setup(tmp_path)
    assert config.dry_run is True  # _compact_setup's own default

    # A prior LIVE (dry_run=False) attempt's state, as only the success path
    # would ever write.
    prior_run_state = {
        "trading_day": "2026-06-29",
        "dry_run": False,
        "run_classification": {"stream": "afternoon", "manual_run": False, "scheduled_for_et": "15:30"},
    }
    with open(os.path.join(artifacts_dir, "run_state.json"), "w", encoding="utf-8") as handle:
        json.dump(prior_run_state, handle)
    with open(os.path.join(artifacts_dir, "orders.csv"), "w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=_CSV_FIELDS)
        writer.writeheader()
        writer.writerow(
            {field: "" for field in _CSV_FIELDS}
            | {
                "ticker": "ZZZZ_LIVE_SENTINEL",
                "status": "filled",
                "order_id": "sentinel-order-id",
            }
        )

    # THIS invocation is dry_run=True (config.dry_run) -- not a retry of the
    # live attempt above, despite matching day/stream/slot/origin.
    run_daily_compact(
        now,
        config,
        state,
        fin,
        rh,
        broker,
        options=CompactRunOptions(artifacts_dir=artifacts_dir, run_label="daily", scheduled=True),
    )

    with open(os.path.join(artifacts_dir, "orders.csv"), encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    tickers = {row["ticker"] for row in rows}
    assert "ZZZZ_LIVE_SENTINEL" not in tickers, (
        "a live attempt's execution row was merged into a dry-run retry's orders.csv"
    )


def test_run_daily_compact_never_merges_two_manual_runs(tmp_path):
    """A manual run's classification never carries stream/scheduled_for_et
    (build_manual_classification stamps neither), so two UNRELATED manual
    invocations sharing the same artifacts_dir and trading_day would
    otherwise look identical to a genuine retry -- despite each getting its
    own distinct run_id (Codex review: "Keep distinct manual runs out of
    retry merges"). Since nothing else here can tell them apart, manual runs
    must never be merged at all.
    """
    from near_close_dca import _CSV_FIELDS

    artifacts_dir = os.path.join(tmp_path, "runs", "2026-06-29")
    os.makedirs(artifacts_dir, exist_ok=True)
    now, config, state, broker, fin, rh = _compact_setup(tmp_path)

    # A prior, UNRELATED manual run's state.
    prior_run_state = {
        "trading_day": "2026-06-29",
        "dry_run": True,
        "run_classification": {"run_origin": "manual", "manual_run": True, "run_id": "manual-run-A"},
    }
    with open(os.path.join(artifacts_dir, "run_state.json"), "w", encoding="utf-8") as handle:
        json.dump(prior_run_state, handle)
    with open(os.path.join(artifacts_dir, "orders.csv"), "w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=_CSV_FIELDS)
        writer.writeheader()
        writer.writerow(
            {field: "" for field in _CSV_FIELDS}
            | {
                "ticker": "ZZZZ_MANUAL_A_SENTINEL",
                "status": "filled",
                "order_id": "sentinel-order-id",
            }
        )

    # A SECOND, unrelated manual run reuses the same directory the same day.
    run_daily_compact(
        now,
        config,
        state,
        fin,
        rh,
        broker,
        options=CompactRunOptions(artifacts_dir=artifacts_dir, run_label="daily", scheduled=False),
    )

    with open(os.path.join(artifacts_dir, "orders.csv"), encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    tickers = {row["ticker"] for row in rows}
    assert "ZZZZ_MANUAL_A_SENTINEL" not in tickers, (
        "an unrelated manual run's execution row was merged into this manual run's orders.csv"
    )


def test_deployment_history_root_engages_kill_switch_on_later_run(tmp_path):
    # Day 1: a scheduled run deploys real capital under a small monthly allocation
    # so its total trivially exceeds the 40% kill-switch threshold.
    history_root = os.path.join(tmp_path, "runs")
    day1_dir = os.path.join(history_root, "2026-06-29")
    # 2026-07-02 (not 2026-07-03, the observed Independence Day) so the new
    # NYSE-holiday execution gate doesn't block day 2 below.
    day1_dates = frozenset({date(2026, 6, 29), date(2026, 7, 2)})

    now1 = datetime(2026, 6, 29, 15, 45, tzinfo=EASTERN)
    config = StrategyConfig(
        # dry_run=False so candidates land as status="submitted" (deployed_usd only
        # counts submitted candidates) -- DryRunBroker still simulates the fill.
        dry_run=False,
        tickers=("AAPL", "NVDA", "MSFT"),
        approved_test_dates=day1_dates,
        monthly_cash_allocation_usd=10.0,  # tiny allocation -> trivial to exceed 40%
    )
    state1 = StrategyState()
    broker1 = DryRunBroker(cash=500.0, reference_prices={t: 98.0 for t in config.tickers})
    fin1 = _FakeData(SourceName.FINANCE, 98.0, 100.0, quote=(98.0, now1))
    # Tight bid/ask so the scheduled-run fail-closed-on-missing-spread breaker
    # doesn't block this kill-switch scenario (spread behavior is not under test).
    rh1 = _FakeDataWithBidAsk(SourceName.ROBINHOOD, 98.0, 100.0, quote=(98.0, now1), bid_ask=(97.9, 98.1))
    run_daily_compact(
        now1,
        config,
        state1,
        fin1,
        rh1,
        broker1,
        options=CompactRunOptions(artifacts_dir=day1_dir),
    )

    with open(os.path.join(day1_dir, "run_state.json"), encoding="utf-8") as handle:
        day1_state = json.load(handle)
    day1_deployed = sum(c["planned_amount_usd"] for c in day1_state["buy_candidates"] if c["status"] == "submitted")
    assert day1_deployed > 0.4 * config.monthly_cash_allocation_usd  # sanity: threshold is crossed

    # Day 2 (within the trailing 7 days): the kill-switch must engage from day 1's
    # history alone, capping every buy multiplier to 1x.
    day2_dir = os.path.join(history_root, "2026-07-02")
    now2 = datetime(2026, 7, 2, 15, 45, tzinfo=EASTERN)
    state2 = StrategyState()
    broker2 = DryRunBroker(cash=500.0, reference_prices={t: 98.0 for t in config.tickers})
    fin2 = _FakeData(SourceName.FINANCE, 98.0, 100.0, quote=(98.0, now2))
    rh2 = _FakeDataWithBidAsk(SourceName.ROBINHOOD, 98.0, 100.0, quote=(98.0, now2), bid_ask=(97.9, 98.1))
    run_daily_compact(
        now2,
        config,
        state2,
        fin2,
        rh2,
        broker2,
        options=CompactRunOptions(artifacts_dir=day2_dir, deployment_history_root=history_root),
    )

    with open(os.path.join(day2_dir, "run_state.json"), encoding="utf-8") as handle:
        day2_state = json.load(handle)
    assert day2_state["risk_guard"]["kill_switch_engaged"] is True
    submitted = [c for c in day2_state["buy_candidates"] if c["status"] == "submitted"]
    assert submitted  # the guard caps sizing, it doesn't block buying entirely
    assert all(c["buy_multiplier"] == 1.0 for c in submitted)
    day2_deployed = sum(c["planned_amount_usd"] for c in submitted)
    # The reported trailing-7-day figure reflects day 1's history PLUS day 2's
    # own submissions as they were made (see
    # test_kill_switch_caps_later_candidates_within_the_same_batch for the
    # narrower in-batch behavior) -- not just the pre-run historical figure.
    assert day2_state["risk_guard"]["deployed_last_7d_usd"] == round(day1_deployed + day2_deployed, 2)


def test_recovered_fractional_notional_survives_deployment_history_injection(tmp_path):
    """A recovered ambiguous placement's dollars must still be reflected in
    THIS run's in-memory kill-switch figure even when deployment_history_root
    is configured. _apply_deployment_history REPLACES deployed_last_7d_usd
    wholesale with the disk-scanned trailing-seven-day figure (a full
    dataclasses.replace, never additive) -- so a bump applied before that
    call is silently discarded (Codex review, PR #911 round 2: "Apply
    recovered deployment after loading history").

    The prior artifact is given a REAL scheduled afternoon classification and
    timestamp, not a bare hand-crafted stub: _apply_deployment_history's scan
    only counts a row that passes dca_risk.is_afternoon_scheduled_evidence,
    and the recovered order's own buy_candidates row is appended to THIS
    SAME file during reconciliation (Codex review, PR #911 round 4: "Publish
    each recovered group before processing the next") -- before that scan
    runs. When deployment_history_root covers this artifacts_dir, as it does
    here, the scan therefore already counts the recovered $50, and the
    manual bump must NOT add it again (Codex review, PR #911 round 7: "Avoid
    adding recovered notional already loaded from history")."""
    from scripts.run_classification import build_scheduled_classification

    history_root = os.path.join(tmp_path, "runs")
    artifacts_dir = os.path.join(history_root, "2026-06-29")
    os.makedirs(artifacts_dir)
    now, config, state, _broker, fin, rh = _compact_setup(tmp_path)
    config = StrategyConfig(
        dry_run=False,
        tickers=config.tickers,
        approved_test_dates=config.approved_test_dates,
    )
    trading_day_iso = now.date().isoformat()
    triggered_at_utc = now.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")
    with open(os.path.join(artifacts_dir, "run_state.json"), "w", encoding="utf-8") as handle:
        json.dump(
            {
                "trading_day": trading_day_iso,
                "generated_at": triggered_at_utc,
                "run_classification": build_scheduled_classification(
                    trading_day_iso, triggered_at_utc=triggered_at_utc
                ),
                "broker_outcomes": {
                    "AAPL": {
                        "status": "failed",
                        "placement_outcome_unproven": True,
                        "placement_ref_id": "afternoon-AAPL-proof",
                        "submitted_amount_usd": 50.0,
                    }
                },
            },
            handle,
        )

    class Broker(DryRunBroker):
        def same_day_order_with_ref_id_prefix_any_state(self, ticker, trading_day, ref_id_prefixes):
            return {"id": "ORD-RECOVERED", "state": "queued", "dollar_amount": "50.00"}

    broker = Broker(cash=500.0, reference_prices={t: 98.0 for t in config.tickers})
    run_daily_compact(
        now,
        config,
        state,
        fin,
        rh,
        broker,
        options=CompactRunOptions(artifacts_dir=artifacts_dir, deployment_history_root=history_root),
    )

    with open(os.path.join(artifacts_dir, "run_state.json"), encoding="utf-8") as handle:
        run_state = json.load(handle)
    # This run's OWN fresh submitted candidates, excluding the recovered
    # row itself, computed from the artifact so this assertion does not
    # hardcode an unrelated ladder-sizing total.
    own_new_submitted = sum(
        c["planned_amount_usd"]
        for c in run_state["buy_candidates"]
        if c.get("status") == "submitted" and c.get("reason") != "reconciled_fractional_placement"
    )
    # EXACTLY the recovered $50 plus this run's own new submissions -- not
    # double the $50, which is what reappears if the history scan's own
    # count of the just-appended recovery row and the manual bump both add
    # it.
    assert run_state["risk_guard"]["deployed_last_7d_usd"] == round(50.0 + own_new_submitted, 2)


def test_recovered_fractional_notional_still_counted_when_the_scan_skips_it(tmp_path):
    """Directory containment is not proof the deployment-history scan
    actually counted this order: a legacy afternoon failure artifact
    without a valid scheduled classification/timestamp is skipped by
    _apply_deployment_history's scan (dca_risk.is_afternoon_scheduled_
    evidence requires one) even though it physically sits inside
    deployment_history_root. The reconciler's own permissive run-type check
    (a missing classification classifies STREAM_OTHER, not a hard reject)
    still accepts and republishes such a recovery, so skipping the manual
    bump purely because the artifact is path-contained under-stated
    running_deployed_7d for the rest of this batch (Codex review, PR #911
    round 9: "Verify the history scan counted the recovered row")."""
    history_root = os.path.join(tmp_path, "runs")
    artifacts_dir = os.path.join(history_root, "2026-06-29")
    os.makedirs(artifacts_dir)
    now, config, state, _broker, fin, rh = _compact_setup(tmp_path)
    config = StrategyConfig(
        dry_run=False,
        tickers=config.tickers,
        approved_test_dates=config.approved_test_dates,
    )
    trading_day_iso = now.date().isoformat()
    # No run_classification at all -- classify_stream() reads this as
    # STREAM_OTHER, which _apply_deployment_history's scan never counts as
    # scheduled evidence, but the reconciler's own permissive run-type check
    # still accepts and republishes it.
    with open(os.path.join(artifacts_dir, "run_state.json"), "w", encoding="utf-8") as handle:
        json.dump(
            {
                "trading_day": trading_day_iso,
                "broker_outcomes": {
                    "AAPL": {
                        "status": "failed",
                        "placement_outcome_unproven": True,
                        "placement_ref_id": "afternoon-AAPL-proof",
                        "submitted_amount_usd": 50.0,
                    }
                },
            },
            handle,
        )

    class Broker(DryRunBroker):
        def same_day_order_with_ref_id_prefix_any_state(self, ticker, trading_day, ref_id_prefixes):
            return {"id": "ORD-RECOVERED", "state": "queued", "dollar_amount": "50.00"}

    broker = Broker(cash=500.0, reference_prices={t: 98.0 for t in config.tickers})
    run_daily_compact(
        now,
        config,
        state,
        fin,
        rh,
        broker,
        options=CompactRunOptions(artifacts_dir=artifacts_dir, deployment_history_root=history_root),
    )

    with open(os.path.join(artifacts_dir, "run_state.json"), encoding="utf-8") as handle:
        run_state = json.load(handle)
    own_new_submitted = sum(
        c["planned_amount_usd"]
        for c in run_state["buy_candidates"]
        if c.get("status") == "submitted" and c.get("reason") != "reconciled_fractional_placement"
    )
    # The scan skipped the recovered row (no valid scheduled classification),
    # so the manual bump must still add the recovered $50 -- omitting it
    # would understate deployed_last_7d_usd for the rest of this batch.
    assert run_state["risk_guard"]["deployed_last_7d_usd"] == round(50.0 + own_new_submitted, 2)


def test_recovered_fractional_notional_excluded_from_manual_deployment(tmp_path):
    """deployed_last_7d_usd is the SCHEDULED-live kill-switch total --
    deployment-history scanning already excludes manual artifacts, and
    every ordinary placement's own bump to this figure is gated on
    ctx.scheduled. A MANUAL invocation (scheduled=False) reconciling a
    same-day ambiguous placement still gets the recovery back from
    _reconcile_prior_unproven_fractional_placements -- correctly, for
    booking into ctx.state/today's candidates -- but bumping this
    SCHEDULED figure from it too published an inflated risk-guard total
    that could make a later candidate in this manual run appear to cross
    a threshold that was never actually approached (Codex review, PR #911
    round 19: "Exclude manual recoveries from scheduled deployment")."""
    history_root = os.path.join(tmp_path, "runs")
    artifacts_dir = os.path.join(history_root, "2026-06-29-manual")
    os.makedirs(artifacts_dir)
    now, config, state, _broker, fin, rh = _compact_setup(tmp_path)
    config = StrategyConfig(
        dry_run=False,
        tickers=config.tickers,
        approved_test_dates=config.approved_test_dates,
    )
    trading_day_iso = now.date().isoformat()
    with open(os.path.join(artifacts_dir, "run_state.json"), "w", encoding="utf-8") as handle:
        json.dump(
            {
                "trading_day": trading_day_iso,
                "run_classification": {"run_origin": "manual"},
                "broker_outcomes": {
                    "AAPL": {
                        "status": "failed",
                        "placement_outcome_unproven": True,
                        "placement_ref_id": "afternoon-AAPL-proof",
                        "submitted_amount_usd": 50.0,
                    }
                },
            },
            handle,
        )

    class Broker(DryRunBroker):
        def same_day_order_with_ref_id_prefix_any_state(self, ticker, trading_day, ref_id_prefixes):
            return {"id": "ORD-RECOVERED-MANUAL", "state": "queued", "dollar_amount": "50.00"}

    broker = Broker(cash=500.0, reference_prices={t: 98.0 for t in config.tickers})
    run_daily_compact(
        now,
        config,
        state,
        fin,
        rh,
        broker,
        options=CompactRunOptions(
            artifacts_dir=artifacts_dir,
            deployment_history_root=history_root,
            scheduled=False,
        ),
    )

    with open(os.path.join(artifacts_dir, "run_state.json"), encoding="utf-8") as handle:
        run_state = json.load(handle)
    # The recovery itself still happened...
    assert any(c.get("reason") == "reconciled_fractional_placement" for c in run_state["buy_candidates"])
    # ...but the SCHEDULED kill-switch figure must not reflect it (nor, for
    # a manual run, this run's own ordinary submissions either -- every
    # bump to this figure is gated on ctx.scheduled the same way).
    assert run_state["risk_guard"]["deployed_last_7d_usd"] == 0.0


def test_recovered_fractional_notional_excluded_from_morning_deployment(tmp_path):
    """deployed_last_7d_usd is specifically the AFTERNOON kill-switch total
    -- dca_risk.is_afternoon_scheduled_evidence() (which the preceding
    deployment-history scan already runs through) explicitly excludes
    morning and midday evidence, mirroring the inverse-Martingale recovery
    loop's own `im_claim_is_afternoon` gate. Before this fix, the bump here
    was gated on `scheduled` alone: when the shared engine ran a SCHEDULED
    MORNING (or midday) slot and reconciled that slot's own same-day
    ambiguous placement, the preceding history scan never counted it (not
    afternoon evidence) but this bump still added it, inflating the
    afternoon-scoped kill-switch total with capital it is defined to
    exclude and spuriously capping later candidates in this same
    non-afternoon run (Codex review, PR #911 round 29: "Exclude morning
    recoveries from afternoon deployment")."""
    history_root = os.path.join(tmp_path, "runs")
    artifacts_dir = os.path.join(history_root, "2026-06-29-morning")
    os.makedirs(artifacts_dir)
    now, config, state, _broker, fin, rh = _compact_setup(tmp_path)
    config = StrategyConfig(
        dry_run=False,
        tickers=config.tickers,
        approved_test_dates=config.approved_test_dates,
    )
    trading_day_iso = now.date().isoformat()
    with open(os.path.join(artifacts_dir, "run_state.json"), "w", encoding="utf-8") as handle:
        json.dump(
            {
                "trading_day": trading_day_iso,
                "run_classification": {"stream": "morning", "scheduled_for_et": "10:30"},
                "broker_outcomes": {
                    "AAPL": {
                        "status": "failed",
                        "placement_outcome_unproven": True,
                        "placement_ref_id": "morning-AAPL-proof",
                        "submitted_amount_usd": 50.0,
                    }
                },
            },
            handle,
        )

    class Broker(DryRunBroker):
        def same_day_order_with_ref_id_prefix_any_state(self, ticker, trading_day, ref_id_prefixes):
            return {"id": "ORD-RECOVERED-MORNING", "state": "queued", "dollar_amount": "50.00"}

    broker = Broker(cash=500.0, reference_prices={t: 98.0 for t in config.tickers})
    run_daily_compact(
        now,
        config,
        state,
        fin,
        rh,
        broker,
        options=CompactRunOptions(
            artifacts_dir=artifacts_dir,
            deployment_history_root=history_root,
            scheduled=True,
            stream="morning",
        ),
    )

    with open(os.path.join(artifacts_dir, "run_state.json"), encoding="utf-8") as handle:
        run_state = json.load(handle)
    # The recovery itself still happened...
    assert any(c.get("reason") == "reconciled_fractional_placement" for c in run_state["buy_candidates"])
    # ...but the AFTERNOON-scoped kill-switch figure must not reflect a
    # morning slot's own $50 recovery -- only this run's own new (unrelated)
    # submissions, which bump the same figure regardless of stream, not
    # hardcoded here since the exact ladder-sizing total is unrelated to
    # this fix.
    own_new_submitted = sum(
        c["planned_amount_usd"]
        for c in run_state["buy_candidates"]
        if c.get("status") == "submitted" and c.get("reason") != "reconciled_fractional_placement"
    )
    assert run_state["risk_guard"]["deployed_last_7d_usd"] == round(own_new_submitted, 2)


