    from scripts.run_classification import (
        CRON_ID,
        SCHEDULED_FOR_ET,
        SCHEDULED_RUN_TYPE,
        SCHEDULED_WINDOW_END_ET,
        SCHEDULED_WINDOW_START_ET,
    )

    replay_day = date(2026, 7, 21)
