    now, config, state, _broker, fin, rh = _compact_setup(tmp_path)
    artifacts_dir = tmp_path / "non-object-run-state"
    artifacts_dir.mkdir()
    (artifacts_dir / "run_state.json").write_text("[]", encoding="utf-8")
