    message = "-----BEGIN CERTIFICATE-----BEGIN PRIVATE KEY-----SECRETVALUE-----END PRIVATE KEY-----"
    text = near_close_dca._redacted_diagnostic_text(message)
    assert "SECRETVALUE" not in text


