def test_archive_intraday_observations_locks_read_modify_write(tmp_path, monkeypatch):
    # The annotation read and atomic replacement must share the same sidecar
    # critical section used by the primary run-state publisher (Codex review:
    # "Lock every run-state read-modify-write"). This replaces an earlier
    # pre/post-stat compare, which only detected a concurrent writer AFTER
    # racing it -- a real TOCTOU window remained between the check and the
    # write. Holding the sidecar lock across the whole read-modify-write
    # instead makes that race structurally impossible for any writer that
    # takes the same lock, which every run_state.json writer in this module
    # now does.
    import near_close_dca as m

    monkeypatch.setattr(m, "write_run_snapshot", lambda out, observations: None)
    monkeypatch.setattr(m, "archive_observations_safely", lambda observations: {"ok": True})

    run_state_path = tmp_path / "run_state.json"
    run_state_path.write_text(json.dumps({"run_id": "r1", "signal_rows": [], "status": "ok"}))
    lock_active = False

    class RecordingLock:
        def __enter__(self):
            nonlocal lock_active
            lock_active = True

        def __exit__(self, *args):
            nonlocal lock_active
            lock_active = False

    def recording_lock(path):
        assert path == tmp_path / "run_state.json.lock"
        return RecordingLock()

    real_read_bytes = pathlib.Path.read_bytes
    real_atomic_write = m.atomic_write_text

    def checked_read_bytes(self):
        if self == run_state_path:
            assert lock_active
        return real_read_bytes(self)

    def checked_atomic_write(path, text):
        if path == run_state_path:
            assert lock_active
        return real_atomic_write(path, text)

    monkeypatch.setattr(m, "cross_process_lock", recording_lock)
    monkeypatch.setattr(pathlib.Path, "read_bytes", checked_read_bytes)
    monkeypatch.setattr(m, "atomic_write_text", checked_atomic_write)

    artifacts = {"run_id": "r1", "signal_rows": [], "trading_day": "2026-08-03"}
    m._archive_intraday_observations(artifacts, tmp_path, run_state_path=run_state_path)

    persisted = json.loads(real_read_bytes(run_state_path))
    assert persisted["status"] == "ok"
    assert persisted["intraday_archive"]["ok"] is True


def test_select_reconciled_signal_rows_picks_the_buy_winning_provider(tmp_path):
    # Codex review ("Archive one reconciled near-close observation per
    # ticker"): at 15:30 signal_rows carries two rows per ticker (Finance
    # then Robinhood), and the scheduled natural key
    # (trading_day, stream, slot, ticker) has no source component, so
    # archiving both unfiltered would collapse to whichever sorts last --
    # Robinhood here -- even when Finance is the one that actually produced
    # the reconciled BUY.
    finance_signal = SourceSignal(
        ticker="AAPL",
        source=SourceName.FINANCE,
        action=Action.BUY,
        reason="ok",
        decision_price=98.0,
        quote_price=98.0,
    )
    robinhood_signal = SourceSignal(
        ticker="AAPL",
        source=SourceName.ROBINHOOD,
        action=Action.BUY,
        reason="ok",
        decision_price=97.0,
        quote_price=97.0,
    )
    decision = ReconciledDecision(
        ticker="AAPL",
        action=Action.BUY,
        reason="finance and Robinhood agree on BUY",
        finance_signal=finance_signal,
        robinhood_signal=robinhood_signal,
        target_price=98.0,
        target_price_source="finance:signal_quote",
    )
    signal_rows = [
        {"ticker": "AAPL", "source": "finance", "decision_bar_close": 98.0},
        {"ticker": "AAPL", "source": "robinhood", "decision_bar_close": 97.0},
    ]

    selected = _select_reconciled_signal_rows(signal_rows, [decision])

    assert len(selected) == 1
    row = selected[0]
    assert row["ticker"] == "AAPL"
    assert row["source"] == "finance"
    assert row["decision_bar_close"] == 98.0
    # Codex review ("Archive the near-close target quote"): the row must
    # also carry the RECONCILED execution target, not just the raw
    # decision_bar_close, so the archived price matches what placement
    # actually used.
    assert row["current_price"] == 98.0
    assert row["price_source"] == "finance:signal_quote"


